#!/usr/bin/env python3
"""
Independent R07 audit of R08-L003.

The script independently reconstructs the K=5 local-self-avoidance automaton,
uses a separately regenerated integer Collatz certificate (scale 1e10 rather
than R08's archived 1e8 certificate), and verifies the exact rational
inequalities needed for the claimed bound mu(e1) >= 3753/12500.

All PASS decisions below are exact Fraction/integer comparisons. Floating
point was used only offline to *find* the integer vector V2; the vector is
hard-coded here and the checker itself does not rely on floats.
"""
from fractions import Fraction
from itertools import product

DIRS=((1,0),(-1,0),(0,1),(0,-1))
K=5
Z=Fraction(22,7)
LAM=Fraction(2407,500)
MARKOV=Fraction(38141,10000)
C=Fraction(3753,12500)
V2=[764563162782, 638846936444, 638846936444, 762836018828, 122208284409, 639039736898, 762836018828, 122208284409, 639039736898, 764456621204, 638973201626, 630741046118, 117404981555, 550954487446, 762478632924, 127385672769, 639443740182, 764456621204, 630741046118, 638973201626, 117404981555, 550954487446, 762478632924, 127385672769, 639443740182, 764563162782, 638846936444, 638334045342, 762836018828, 124118640331, 639039736898, 762836018828, 638902439192, 220252359509, 495107224277, 139139682595, 630787900133, 151297126602, 621678365223, 764456621204, 638973201626, 629020590562, 164308808333, 550954487446, 10000000000, 762478632924, 133498126372, 639443740182, 764563162782, 638334045342, 638846936444, 762836018828, 638902439192, 762836018828, 124118640331, 639039736898, 220252359509, 139139682595, 495107224277, 630787900133, 151297126602, 621678365223, 764456621204, 629020590562, 638973201626, 164308808333, 10000000000, 550954487446, 762478632924, 133498126372, 639443740182, 220252359509, 495107224277, 495107224277, 545245133220, 151297126602, 621678365223, 545245133220, 151297126602, 621678365223, 631857096085, 638973201626, 164308808333, 550954487446, 125109726388, 735266926513, 133498126372, 639443740182, 631857096085, 638973201626, 164308808333, 125109726388, 550954487446, 735266926513, 133498126372, 639443740182, 764563162782, 638846936444, 630769566625, 762836018828, 124118640331, 639039736898, 220252359509, 495107224277, 225794997852, 630787900133, 151297126602, 621678365223, 151297126602, 554138163298, 764456621204, 638973201626, 498023449975, 164308808333, 550954487446, 39425348484, 762478632924, 133498126372, 639443740182, 764563162782, 630769566625, 638846936444, 762836018828, 124118640331, 639039736898, 220252359509, 225794997852, 495107224277, 151297126602, 554138163298, 630787900133, 151297126602, 621678365223, 764456621204, 498023449975, 638973201626, 164308808333, 39425348484, 550954487446, 762478632924, 133498126372, 639443740182, 764563162782, 638846936444, 638846936444, 762836018828, 122208284409, 639039736898, 762836018828, 114448389414, 639039736898, 764456621204, 638973201626, 630741046118, 146308117730, 550954487446, 762478632924, 127385672769, 639443740182, 764456621204, 630741046118, 638973201626, 762478632924, 125308397930, 639443740182, 220252359509, 495107224277, 495107224277, 545245133220, 151297126602, 621678365223, 132732295445, 151297126602, 621678365223, 762885271073, 638973201626, 164308808333, 550954487446, 125109726388, 735266926513, 133498126372, 639443740182, 164308808333, 125109726388, 550954487446, 631813768333, 133498126372, 639443740182, 764563162782, 638846936444, 638334045342, 762836018828, 124118640331, 639039736898, 762836018828, 630620167033, 220252359509, 495107224277, 225794997852, 630787900133, 151297126602, 621678365223, 151297126602, 141653612384, 764456621204, 638973201626, 629020590562, 164308808333, 550954487446, 39425348484, 762478632924, 133498126372, 639443740182, 764563162782, 638846936444, 638846936444, 762836018828, 114448389414, 639039736898, 762836018828, 122208284409, 639039736898, 764456621204, 638973201626, 630741046118, 762478632924, 125308397930, 639443740182, 764456621204, 630741046118, 638973201626, 146308117730, 550954487446, 762478632924, 127385672769, 639443740182, 220252359509, 495107224277, 495107224277, 132732295445, 151297126602, 621678365223, 545245133220, 151297126602, 621678365223, 164308808333, 550954487446, 125109726388, 631813768333, 133498126372, 639443740182, 762885271073, 638973201626, 164308808333, 125109726388, 550954487446, 735266926513, 133498126372, 639443740182, 764563162782, 638334045342, 638846936444, 762836018828, 630620167033, 762836018828, 124118640331, 639039736898, 220252359509, 225794997852, 495107224277, 151297126602, 141653612384, 630787900133, 151297126602, 621678365223, 764456621204, 629020590562, 638973201626, 164308808333, 39425348484, 550954487446, 762478632924, 133498126372, 639443740182]

states=[]
for ds in product(range(4), repeat=K):
    x=y=0
    seen={(0,0)}
    ok=True
    for d in ds:
        dx,dy=DIRS[d]
        x+=dx; y+=dy
        if (x,y) in seen:
            ok=False
            break
        seen.add((x,y))
    if ok:
        states.append(ds)
idx={s:i for i,s in enumerate(states)}

trans=[]
for s in states:
    x=y=0
    seen={(0,0)}
    for d in s:
        dx,dy=DIRS[d]
        x+=dx; y+=dy
        seen.add((x,y))
    row=[]
    for d in range(4):
        dx,dy=DIRS[d]
        nx,ny=x+dx,y+dy
        if (nx,ny) in seen:
            continue
        ns=s[1:]+(d,)
        assert ns in idx
        row.append((idx[ns],d))
    trans.append(row)

assert len(states)==284
assert sum(map(len,trans))==780
assert len(V2)==284 and min(V2)>0

max_ratio=Fraction(0,1)
max_i=-1
for i,row in enumerate(trans):
    mv=Fraction(0,1)
    for j,d in row:
        dx=DIRS[d][0]
        w=Z if dx==1 else (1/Z if dx==-1 else Fraction(1,1))
        mv += w*V2[j]
    assert mv <= LAM*V2[i]
    ratio=mv/V2[i]
    if ratio>max_ratio:
        max_ratio=ratio
        max_i=i

rho=LAM/(1+MARKOV)
assert rho==Fraction(48140,48141)
assert rho<1

x=MARKOV*C
N=7
term=Fraction(1,1)
exp_upper=term
for j in range(1,N+1):
    term=term*x/j
    exp_upper += term
next_term=term*x/(N+1)
qtail=x/(N+2)
assert qtail<1
exp_upper += next_term/(1-qtail)

threshold=Z*(1+MARKOV)/LAM
assert exp_upper < threshold
base_upper=(exp_upper/Z)*rho
assert base_upper<1

def accepted(ds):
    if len(ds)<K:
        return True
    for start in range(len(ds)-K+1):
        x=y=0
        seen={(0,0)}
        for d in ds[start:start+K]:
            dx,dy=DIRS[d]
            x+=dx; y+=dy
            if (x,y) in seen:
                return False
            seen.add((x,y))
    return True

def globally_simple(ds):
    x=y=0
    seen={(0,0)}
    for d in ds:
        dx,dy=DIRS[d]
        x+=dx; y+=dy
        if (x,y) in seen:
            return False
        seen.add((x,y))
    return True

tested=0
for m in range(1,10):
    for ds in product(range(4), repeat=m):
        if globally_simple(ds):
            assert accepted(ds)
        tested+=1

print("PASS")
print("independent R07 audit of R08-L003")
print("states",len(states),"transitions",sum(map(len,trans)))
print("certificate_scale",10**10)
print("max_collatz_ratio",max_ratio,"at_state",max_i)
print("Lambda",LAM)
print("rho",rho)
print("exp_upper",exp_upper)
print("exp_threshold",threshold)
print("geometric_base_upper",base_upper)
print("finite_language_sanity_cases",tested)
print("claim_checked: exact certificate supports mu(e1) >= 3753/12500, conditional only on the written path-count/Chernoff argument")
